INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425245, 16169, 'South China Morning Post', 'en', 'Hormuz deal presses pause on Iran conflict, but fears of ‘forever war’ remain', 'https://www.scmp.com/week-asia/politics/article/3365532/hormuz-deal-presses-pause-iran-conflict-fears-forever-war-remain', 'A diplomatic push by Oman, Pakistan and Qatar is widely expected to yield another pause in the Iran conflict, but there remains little prospect of a stop to what analysts fear has already become a “forever war”. On Monday, Iran and Oman agreed in principle to a temporary maritime route for ships travelling through the Strait of Hormuz. This could lead to the easing of the tit-for-tat blockades imposed by Iran and the US if President Donald Trump’s administration accepts it. Regional mediators...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/56db6e5c-cb90-4a24-a089-2ce9f2b3dc0a_1d422ea5.jpg?itok=OV7y1MXR&v=1787890348', '2026-08-28T05:00:07+00:00', '2026-08-28T12:53:51.930214'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
