INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427248, 16169, 'The Guardian', 'en', 'Trump announces new US oil agreement with Venezuela', 'https://www.theguardian.com/us-news/2026/aug/28/trump-venezuela-oil-agreement', 'US president says US will have ‘majority’ control of 65bn barrels of proven oil reserves Donald Trump announced Friday a new US oil agreement with Venezuela’s interim president Delcy Rodríguez, saying the US will have “majority” control of 65bn barrels of proven oil reserves. The terms of the agreement remain to be seen, but the US president said on his social-media platform that it had been brokered “through a partnership with ⁠private business” by his secretary of state, Marco Rubio, and defense secretary, Pete Hegseth. Continue reading...', 'https://i.guim.co.uk/img/media/1d68042ed18ea8806bd1af82612aa075ae927bba/408_0_4080_3264/master/4080.jpg?width=140&quality=85&auto=format&fit=max&s=66f72ca7721d87d12ef2f48da2e11f0d', '2026-08-28T23:34:36+00:00', '2026-08-29T00:03:18.534015'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427249, 16169, 'The Guardian', 'en', 'Venezuelan opposition up in arms over reports US wants big stake in oil and gas', 'https://www.theguardian.com/world/2026/aug/28/us-venezuela-oil-gas-stake', 'Critics call move to gain long-term access to country’s massive energy reserves ‘predatory’ and ‘unconstitutional’ Reports that the US is preparing to claim a big stake in Venezuela’s massive energy reserves have sparked an outcry, with critics describing the move as “predatory” and a “rapacious” land grab. Several media outlets this week reported that the Trump administration – which abducted Venezuela’s authoritarian president, Nicolás Maduro, in January and has steered the South American country ever since – hopes to secure long-term access to its oil and gasfields. Continue reading...', 'https://i.guim.co.uk/img/media/64676fb920a4239d768d5b0d0e29d3e8c2e363b2/378_0_3743_2994/master/3743.jpg?width=140&quality=85&auto=format&fit=max&s=6bfc48b9b1cf950fb1f2b0275ffc1d52', '2026-08-28T17:41:37+00:00', '2026-08-29T00:03:18.553943'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
