INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429800, 16169, 'South China Morning Post', 'en', 'Trump says US has deal with Venezuela for control of 65 billion barrels of oil reserves', 'https://www.scmp.com/news/world/americas/article/3365672/trump-says-us-has-deal-venezuela-control-65-billion-barrels-oil-reserves', 'President Donald Trump on Friday said the US has entered an agreement with Venezuela to take control of 65 billion barrels of the South American country’s oil reserves. Trump in a social media post announced the agreement he said was negotiated by Secretary of State Marco Rubio, Defence Secretary Pete Hegseth and Venezuela’s interim President Delcy Rodriguez. “The United States of America has just entered into an Agreement with the Country of Venezuela on, THE BIGGEST OIL DEAL IN WORLD HISTORY!”...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/29/4931fd9c-8804-49dd-b458-9109153723f0_79de22aa.jpg?itok=0xFVcShI&v=1787960475', '2026-08-28T23:41:23+00:00', '2026-08-29T00:09:28.299014'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (429806, 16169, 'South China Morning Post', 'en', 'Trump orders creation of US ‘Space Academy’, amid rivalry with China', 'https://www.scmp.com/news/world/united-states-canada/article/3365667/trump-orders-creation-us-space-academy-amid-rivalry-china', 'US President Donald Trump on Friday announced the creation of a “Space Academy” to train future civilian and military recruits for an arena where the United States faces rivalry with China. Speaking at Nasa’s Johnson Space Centre in Houston, Trump said the institution would be modelled on the famed US military academy at West Point. “It’s called the US Space Academy. That’s a big deal,” Trump said as he signed an executive order creating the new school. “It’ll serve both the United States Space...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/29/39c846aa-8e6e-42e6-94ed-618d1bb3680e_24639799.jpg?itok=ED6qbJSw&v=1787944061', '2026-08-28T19:07:43+00:00', '2026-08-29T00:09:28.487628'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
