INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427259, 16193, 'The Guardian', 'en', 'Man, 41, dies after large sign falls at Christian festival in West Sussex', 'https://www.theguardian.com/uk-news/2026/aug/29/man-41-dies-after-large-sign-falls-at-christian-festival-in-west-sussex', 'Six more people hospitalised after incident at Big Church festival near Steyning A 41-year-old man has died and at least six other people have been injured after a large sign fell at a Christian festival in West Sussex, police said. The man, from Eastbourne, East Sussex, was pronounced dead at the scene after the incident at the Big Church festival near Steyning on Friday afternoon. Continue reading...', 'https://i.guim.co.uk/img/media/162bc1779242029c4aed9db9cf37228d506f97bc/0_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=f49765cdaaa0b095a08b22caff70f882', '2026-08-28T23:07:41+00:00', '2026-08-29T00:03:20.159145'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427260, 16193, 'The Guardian', 'en', 'Police arrest seven more men in aftermath of deadly A66 crash', 'https://www.theguardian.com/uk-news/2026/aug/28/police-arrest-seven-more-men-in-aftermath-of-deadly-a66-crash', 'Cleveland police say a total of 24 people arrested in investigation after crash that killed two officers Seven more men have been arrested as part of an operation tackling alleged organised crime after the head-on crash on the A66 that resulted in seven deaths, Cleveland police have said. Officers said four men, aged 21, 25, 35 and 40, were being held on suspicion of criminal damage with intent to endanger life after a vehicle crashed into a house in Steele Crescent, Middlesbrough. Continue reading...', 'https://i.guim.co.uk/img/media/07fcc222c36d93a58c8f2e243ae4e38b8216b646/320_0_3818_3055/master/3818.jpg?width=140&quality=85&auto=format&fit=max&s=f1d3e170c85ca5d5aec7d472150e0469', '2026-08-28T22:00:46+00:00', '2026-08-29T00:03:20.201130'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
